INSERT INTO `movies` VALUES
('0420b298-d589-4e1d-84c2-f561f8c976ed','I Can Only Imagine 2','i-can-only-imagine-2-2026-1405769','Following the breakout success of the song \'I Can Only Imagine\', MercyMe\'s Bart Millard is living the dream—sold-out arenas, a devoted fanbase, and a thriving career. But behind the spotlight, Bart\'s past threatens the family he\'s built, especially the fragile bond with his son Sam. When hopeful newcomer Tim Timmons joins the band for their biggest tour yet, he unknowingly brings a renewed gratitude to Bart\'s life through their unlikely friendship. Bart soon discovers that Tim carries hardships—and secrets—of his own, forcing him to face his past and repair his relationships with Sam and his wife Shannon before fame costs him what matters most.','https://image.tmdb.org/t/p/w500/qYBCs9nBmdNCLduw5BTlendq89z.jpg','https://image.tmdb.org/t/p/original/qHBnPZA3J6hSl9a3Q1JAQzDeo2L.jpg','https://www.youtube.com/watch?v=8MLqWdUOZYQ',2026,110,8.1,'EN','PUBLISHED','2026-11-23 17:28:47.705','2026-11-23 17:28:47.706','2026-11-23 17:28:47.706'),
('04675b33-3eb2-42f5-b10d-cde53cd85469','Baththa','baththa-2026-1515692','In 1986 Madras, a timid eight-year-old boy accidentally traps a feared gangster inside a deserted school toilet. As the gangster is forced to confront hunger, loneliness and his own vulnerability, an unlikely bond begins to grow between the two.','https://image.tmdb.org/t/p/w500/7wHBYs8HHmTGe4nXLpMEAoDSK2o.jpg','https://image.tmdb.org/t/p/original/5sBnZMT1aJ6cBvehKOzOOLdI6bz.jpg','https://www.youtube.com/watch?v=SQp3Li13tw0',2026,159,8.1,'Hindi (Dubbed)','PUBLISHED',NULL,'2026-11-23 19:14:02.350','2026-11-23 19:14:02.350'),
('07eff3e3-48b6-441e-a03e-f0f07696c78b','3BHK','3bhk-2025-1293849','A middle-class family battles financial hurdles and personal setbacks while pursuing their dream of owning a home in the bustling city.','https://image.tmdb.org/t/p/w500/njq3p81KoTVd0lWqGeudId7WwUn.jpg','https://image.tmdb.org/t/p/original/kCC8cxu23zctMenwXIS3EC2hJnn.jpg',NULL,2025,139,7.1,'Tamil','PUBLISHED',NULL,'2026-11-23 18:19:36.876','2026-11-23 18:20:43.520'),
('087c6a57-2be3-4c92-aeab-3c8af2107659','Saccharine','saccharine-2026-1363387','After succumbing to an obscure weight-loss craze involving the eating of human ashes, lovelorn medical student Hana finds herself haunted by the ghost of the person she\'s eating.','https://image.tmdb.org/t/p/w500/bCHPB5WZy4T0Rerh1GTuQLzU0rF.jpg','https://image.tmdb.org/t/p/original/7NUx7bQAD4lo9yMDbprvIblhWo2.jpg','https://www.youtube.com/watch?v=uIY13LD3RUY',2026,113,7.1,'EN','PUBLISHED','2026-11-23 17:29:46.916','2026-11-23 17:29:46.918','2026-11-23 17:29:46.918'),
('09dea454-089d-461e-937b-fed947e1c0c0','I Love Boosters','i-love-boosters-2026-1227877','A group of shoplifters take aim at a cutthroat fashion maven by stealing from her stores and reselling them at a lower price — what they call \'fashion-forward philanthropy\'.','https://image.tmdb.org/t/p/w500/4pNKIUFy7tkZiBx0rnSmG9ysRy.jpg','https://image.tmdb.org/t/p/original/fBZ9cWUI1yB9Fcs2eoYZ4mmMUmI.jpg','https://www.youtube.com/watch?v=1uUdFPE9Unc',2026,113,6.3,'EN','PUBLISHED','2026-11-23 17:28:48.550','2026-11-23 17:28:48.551','2026-11-23 17:28:48.551'),
('09f10428-c57b-4e72-aa8f-77c7a0eccd85','Above & Below','above-below-2026-1514682','A group of friends\' dream diving vacation turns into a fight for survival when brutal criminals attack their boat in open waters.','https://image.tmdb.org/t/p/w500/7bOuu1SRALGwsG2fLCTvRkCmQBj.jpg','https://image.tmdb.org/t/p/original/lSd6nEnlaeQkswLLUgHC5gyuXyU.jpg','https://www.youtube.com/watch?v=18wdUGRPUY4',2026,95,5.9,'EN','PUBLISHED','2026-11-23 17:28:17.107','2026-11-23 17:28:17.108','2026-11-23 17:28:17.108'),
('0c6e05ff-9657-4987-958d-2871babb4633','How to Make a Killing','how-to-make-a-killing-2026-467905','Disowned at birth by his obscenely wealthy family, blue-collar Becket Redfellow will stop at nothing to reclaim his inheritance, no matter how many relatives stand in his way.','https://image.tmdb.org/t/p/w500/vxMeKC7o5Gi8IHMi6lUgsdprTqv.jpg','https://image.tmdb.org/t/p/original/bkUa5ZDqjQPx6rkxs0hM87vaWVa.jpg','https://www.youtube.com/watch?v=BOFhFuUUQ5Y',2026,105,6.9,'EN','PUBLISHED','2026-11-23 17:28:46.958','2026-11-23 17:28:46.960','2026-11-23 17:28:46.960'),
('0d68f786-131c-4e8f-aa51-8f5a74df92c1','Mass Jathara','mass-jathara-2025-1381405','A transport officer battles a violent drug lord and his criminal clan.','https://image.tmdb.org/t/p/w500/qvSyQdI2Mlpa5X7dRDBmIi30oHT.jpg','https://image.tmdb.org/t/p/original/9jiqrAgC9DoWKte8qc5gis0fWem.jpg',NULL,2025,144,4.5,'Telugu','PUBLISHED',NULL,'2026-11-23 18:20:49.555','2026-11-23 18:20:49.555'),
('0ed0fb61-e83c-4557-892f-764986fb63cc','Drive - The Pretenders','drive-the-pretenders-2026-1596275','A young mechanic fakes an engagement with racing\'s most scandalous star — officially for his reputation, secretly for her own shot behind the wheel. But soon the lie threatens to destroy everything — including what\'s already become so much more than just a deal.','https://image.tmdb.org/t/p/w500/s9syckECnUYhKePQ1A0DC0mFVZ9.jpg','https://image.tmdb.org/t/p/original/hbz4aeVsjnKb2HRoFbbr46Egh8y.jpg','https://www.youtube.com/watch?v=-sV69CJwUwU',2026,103,7.6,'DE','PUBLISHED','2026-11-23 17:28:32.722','2026-11-23 17:28:32.724','2026-11-23 17:28:32.724'),
('0fbadbe6-1141-4e08-bc69-261d8491bc79','Lucky Strike','lucky-strike-2026-1594914','A wounded American soldier fights to survive behind enemy lines during WWII\'s Battle of the Bulge against the Germans, relying on his instinct, spy craft and a hand-radio to evade capture and find his way back to his unit.','https://image.tmdb.org/t/p/w500/kzRAd7mj39ZY3FGNrDdZjqx56tn.jpg','https://image.tmdb.org/t/p/original/uujYvxE9s6KY4SbBZ0ZFN3oBJhW.jpg','https://www.youtube.com/watch?v=vtEnjikCXyA',2026,102,6.3,'EN','PUBLISHED','2026-11-23 17:29:00.322','2026-11-23 17:29:00.323','2026-11-23 17:29:00.323'),
('115adb22-7480-4010-aff9-5bc3bfe5a8b1','Pressure','pressure-2026-1318413','In the tense 72 hours before D-Day, and the fate of the free world hanging in the balance, General Dwight D. Eisenhower and Captain James Stagg face an impossible choice—launch the largest and most dangerous seaborne invasion in history or risk losing the war altogether.','https://image.tmdb.org/t/p/w500/gFjEggtrejCN79r6SXRjM269OtG.jpg','https://image.tmdb.org/t/p/original/apfyLCPVFttB8oXcsLJ7q0NSFLx.jpg','https://www.youtube.com/watch?v=ZGgk-q_6-oA',2026,101,7.7,'EN','PUBLISHED','2026-11-23 17:29:32.192','2026-11-23 17:29:32.193','2026-11-23 17:29:32.193'),
